import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const group = new Group();

  // 1. SETUP THE CHROMATIC/ENGINEERED PALETTE
  const colors = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // Dimensions based on 512x320 source rect ratio (1.6)
  const width = 2.4;
  const height = 1.5;
  const geometry = new PlaneGeometry(width, height, 64, 64);

  // 2. MATERIAL IMPLEMENTATION WITH TSL GRAPHICS
  const material = new MeshStandardNodeMaterial({
    roughness: 0.35,
    metalness: 0.55,
    transparent: true,
  });

  // Load the brushed metal map if available
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = 1000; // Repeat
      tex.wrapT = 1000;
      material.roughnessMap = tex;
      material.needsUpdate = true;
    });
  }

  // TSL node setup for an engineered gradient with thin technical lines
  const uvNode = uv();
  const vGrad = uvNode.y; // 0 to 1 vertical
  const hGrad = uvNode.x; // 0 to 1 horizontal

  // Core plate gradient spanning near-black surface to rich ink
  const baseGradient = mix(
    vec3(colors.surface.r, colors.surface.g, colors.surface.b),
    vec3(colors.ink.r, colors.ink.g, colors.ink.b),
    vGrad
  );

  // Top elegant highlight rim
  const topRim = vGrad.sub(0.985).step(0.0).oneMinus(); 
  // Bottom design red accent line (signal red)
  const redBar = vGrad.sub(0.06).abs().step(0.008).oneMinus();

  // Combine factors elegantly
  const coloredBase = mix(baseGradient, vec3(colors.paper.r, colors.paper.g, colors.paper.b), topRim.mul(0.12));
  const finalColorNode = mix(coloredBase, vec3(colors.accent.r, colors.accent.g, colors.accent.b), redBar);

  material.colorNode = finalColorNode;

  // Create the main panel mesh
  const panelMesh = new Mesh(geometry, material);
  panelMesh.castShadow = true;
  panelMesh.receiveShadow = true;
  group.add(panelMesh);

  // 3. PRODUCT LIGHTING SETUP (Node-local dramatic key & back rim)
  const localKeyLight = new DirectionalLight(colors.paper, 1.2);
  localKeyLight.position.set(2, 3, 4);
  group.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.8);
  localRimLight.position.set(-3, -3, -1);
  group.add(localRimLight);

  // 4. INTRO TRANSITION ANIMATION (rise-in with weighted settle)
  group.position.y -= 0.3;
  group.scale.set(0.95, 0.95, 0.95);

  const introTl = gsap.timeline({ defaults: { overwrite: 'auto' } });
  introTl.to(group.position, {
    y: 0,
    duration: 1.1,
    ease: 'power4.out'
  });
  introTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.3,
    ease: 'elastic.out(1, 0.75)'
  }, 0);

  // Apply cinematic primitives (if any were present)
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](group, prim.params);
        if (inst) activePrimitives.push(inst);
      }
    }
  }

  // 5. CLEANUP INTERFACE
  group.userData = {
    handlers: {},
    cleanup() {
      introTl.kill();
      geometry.dispose();
      material.dispose();
      activePrimitives.forEach(p => p.cleanup?.());
    }
  };

  return group;
}
